#[test]
fn test_contract_field_presence() {
    use crate::game_state::GameState;
    let game = GameState::new();
    let dto = get_estado_jornada(&game);
    let _ = &dto.protagonista.posicion_formal_id;
    let _ = &dto.protagonista.visibilidad;
    let _ = &dto.crisis_activa;
    let _ = &dto.eventos_disponibles;
    let _ = dto.presupuesto_temporal;
}
#[test]
fn test_medidor_stub_values_follow_contract() {
    use crate::game_state::GameState;
    let game = GameState::new();
    let dto = get_estado_jornada(&game);
    for m in dto.protagonista.medidores.iter() {
        assert_eq!(m.valor, 50);
        assert_eq!(m.tendencia, 0);
        assert_eq!(m.umbral_bajo, 25);
        assert_eq!(m.umbral_alto, 75);
    }
}
